.albirr-central-header {
    position: relative;
    width: 100%;
    height: 200px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #0a1f12;
    overflow: hidden;
    border-radius: 22px;
    border: 1px solid rgba(47,107,78,0.18);
    font-family: 'Tajawal','Segoe UI',Tahoma,sans-serif;
    direction: rtl;
}

.albirr-space-layer {
    position: absolute;
    inset: 0;
    z-index: 1;
    background:
        radial-gradient(ellipse 70% 60% at 50% 50%, rgba(20,80,40,0.70) 0%, transparent 70%),
        radial-gradient(ellipse 40% 30% at 20% 80%, rgba(47,107,78,0.25) 0%, transparent 60%),
        radial-gradient(ellipse 35% 25% at 80% 20%, rgba(47,107,78,0.20) 0%, transparent 55%);
}

.albirr-stars {
    position: absolute;
    inset: 0;
    z-index: 2;
    background-image:
        radial-gradient(1px 1px at 12% 18%, rgba(255,255,255,0.35) 0%, transparent 100%),
        radial-gradient(1px 1px at 28% 72%, rgba(255,255,255,0.25) 0%, transparent 100%),
        radial-gradient(1px 1px at 45% 10%, rgba(255,255,255,0.30) 0%, transparent 100%),
        radial-gradient(1px 1px at 60% 55%, rgba(255,255,255,0.20) 0%, transparent 100%),
        radial-gradient(1px 1px at 75% 82%, rgba(255,255,255,0.28) 0%, transparent 100%),
        radial-gradient(1px 1px at 88% 33%, rgba(255,255,255,0.22) 0%, transparent 100%),
        radial-gradient(1.5px 1.5px at 5% 60%, rgba(144,238,144,0.50) 0%, transparent 100%),
        radial-gradient(1px 1px at 35% 40%, rgba(255,255,255,0.18) 0%, transparent 100%),
        radial-gradient(1px 1px at 53% 88%, rgba(255,255,255,0.22) 0%, transparent 100%),
        radial-gradient(1.5px 1.5px at 91% 12%, rgba(144,238,144,0.45) 0%, transparent 100%),
        radial-gradient(1px 1px at 70% 5%, rgba(255,255,255,0.20) 0%, transparent 100%),
        radial-gradient(1px 1px at 18% 90%, rgba(255,255,255,0.15) 0%, transparent 100%),
        radial-gradient(1px 1px at 82% 65%, rgba(255,255,255,0.18) 0%, transparent 100%),
        radial-gradient(1.5px 1.5px at 42% 28%, rgba(144,238,144,0.40) 0%, transparent 100%),
        radial-gradient(1px 1px at 65% 38%, rgba(255,255,255,0.15) 0%, transparent 100%);
}

/* ===== الخلفية الخضراء الفاتحة المتحركة ===== */
.albirr-green-glow {
    position: absolute;
    inset: 0;
    z-index: 2;
    background:
