            { label: 'فتح ورديات البيع', type: 'doctype', target: 'Pos Profile', icon: '🏢' },
            { label: 'واجهة المبيعات', type: 'url', route: '/al-mabeeat', icon: '🛒' },
            { label: 'فواتير البيع', type: 'doctype', target: 'Sales Invoice', icon: '🧾' }
        ]
    };

    const mainCard = document.createElement('div');
    mainCard.className = 'main-card';
