    --text-secondary: #A0A0A0;

    font-family: 'Tajawal', sans-serif;
    direction: rtl;
    background: var(--surface-color);
    width: 100%;
    border-radius: 24px;
    padding: 40px;
    border: 1px solid var(--border-color);
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.8), inset 0 1px 0 rgba(255, 255, 255, 0.05);
    display: flex;
    flex-direction: column;
    gap: 32px;
}

/* ----- قسم الشعار ----- */
.dashboard-widget .header-section {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: 24px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.dashboard-widget .logo-box {
    display: flex;
    flex-direction: column;
}

.dashboard-widget .logo-text {
    font-family: 'Poppins', sans-serif;
    font-size: 2.2rem;
    font-weight: 900;
    letter-spacing: 4px;
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    line-height: 1;
}

.dashboard-widget .logo-subtitle {
    font-size: 0.9rem;
    color: var(--text-secondary);
    font-weight: 500;
    margin-top: 4px;
    letter-spacing: 0.5px;
}

/* ----- قسم الترحيب ----- */
.dashboard-widget .welcome-section {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.dashboard-widget .greeting {
    font-size: 1.2rem;
    color: var(--gold-solid);
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 8px;
}

.dashboard-widget .greeting::before {
    content: '';
    width: 24px;
    height: 2px;
    background: var(--gold-gradient);
    border-radius: 2px;
}

.dashboard-widget .user-name {
    font-size: 2.6rem;
    font-weight: 800;
    color: var(--text-primary);
    line-height: 1.2;
    text-shadow: 0 4px 12px rgba(0,0,0,0.5);
    margin: 0;
}

/* ----- قسم الوقت والتاريخ ----- */
.dashboard-widget .datetime-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

.dashboard-widget .data-card {
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 16px;
    padding: 20px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    transition: all 0.3s ease;
}

.dashboard-widget .data-card:hover {
    background: var(--surface-hover);
    border-color: rgba(212, 175, 55, 0.3);
}

.dashboard-widget .card-label {
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 12px;
    font-weight: 500;
}

.dashboard-widget .time-wrapper {
    display: flex;
    align-items: center;
    gap: 8px;
}

.dashboard-widget .live-time {
    font-family: 'Poppins', sans-serif;
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--gold-solid);
}

.dashboard-widget .pulse-indicator {
    width: 8px;
    height: 8px;
    background-color: var(--gold-solid);
    border-radius: 50%;
    animation: pulse-gold 2s infinite;
}

@keyframes pulse-gold {
    0% { box-shadow: 0 0 0 0 rgba(212, 175, 55, 0.4); }
    70% { box-shadow: 0 0 0 10px rgba(212, 175, 55, 0); }
    100% { box-shadow: 0 0 0 0 rgba(212, 175, 55, 0); }
}

/* تنسيق التاريخ الذي يولده كود الـ JS الخاص بك */
.dashboard-widget .greg-line {
    font-size: 0.95rem;
    color: var(--text-secondary);
    font-weight: 500;
    margin-bottom: 6px;
}

.dashboard-widget .hijri-line {
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--text-primary);
}

/* ----- الفوتر ----- */
.dashboard-widget .footer-note {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 14px;
    background: rgba(212, 175, 55, 0.05);
    border-radius: 12px;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--gold-muted);
    border: 1px solid rgba(212, 175, 55, 0.1);
}

.dashboard-widget .footer-note svg {
    width: 18px;
    height: 18px;
    fill: currentColor;
}

@media (max-width: 600px) {
    .dashboard-widget { padding: 30px 20px; }
    .dashboard-widget .datetime-grid { grid-template-columns: 1fr; }
}

script:
// الوصول للعناصر عبر root_element
let btnStep2 = root_element.querySelector('#btn-show-step-2');
let step2Container = root_element.querySelector('#step-2-container');
let btnWatch = root_element.querySelector('#btn-watch-now');
let videoContainer = root_element.querySelector('#video-frame-container');

// إظهار زر المشاهدة عند الضغط على "فيديو الشرح"
if (btnStep2) {
    btnStep2.onclick = function() {
        if (step2Container.style.display === 'none') {
            step2Container.style.display = 'block';
        } else {
            step2Container.style.display = 'none';
            videoContainer.style.display = 'none';
        }
    };
}

// إظهار الفيديو عند الضغط على "مشاهدة الآن"
if (btnWatch) {
    btnWatch.onclick = function() {
        if (videoContainer.style.display === 'none') {
            videoContainer.style.display = 'block';
        } else {
            videoContainer.style.display = 'none';
        }
    };
}

